def canConvertString(s: str, t: str, k: int) -> bool:
    if len(s) != len(t):
        return False

    shifts = [0] * 26
    max_shifts = [0] * 26

    for i in range(1, 27):
        max_shifts[i - 1] = (k // 26) * i + min(k % 26, i)

    for i in range(len(s)):
        diff = (ord(t[i]) - ord(s[i])) % 26
        if diff != 0:
            if shifts[diff] >= max_shifts[diff]:
                return False
            shifts[diff] += 26

    return True
